import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, mapJob } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}
function error(res: ServerResponse, status: number, code: string, message: string, fields?: { field: string; message: string }[]): void {
  send(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
}
async function readBody(req: IncomingMessage): Promise<string> {
  const chunks: Buffer[] = [];
  let size = 0;
  for await (const chunk of req) {
    const b = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
    size += b.length;
    if (size > 1024 * 1024) throw new Error('too_large');
    chunks.push(b);
  }
  return Buffer.concat(chunks).toString('utf8');
}
const fieldsFor = (obj: Record<string, unknown>): { field: string; message: string }[] => {
  const fields: { field: string; message: string }[] = [];
  for (const key of Object.keys(obj)) if (!['input', 'steps', 'failAttempts'].includes(key)) fields.push({ field: key, message: 'Unknown field.' });
  if (typeof obj.input !== 'string') fields.push({ field: 'input', message: 'Must be a string.' });
  else {
    if (obj.input.length < 1 || obj.input.length > 1000) fields.push({ field: 'input', message: 'Must be 1 to 1000 characters.' });
    if (!obj.input.trim()) fields.push({ field: 'input', message: 'Must not be only whitespace.' });
  }
  if (obj.steps !== undefined && (!Number.isInteger(obj.steps) || (obj.steps as number) < 1 || (obj.steps as number) > 20)) fields.push({ field: 'steps', message: 'Must be an integer from 1 to 20.' });
  if (obj.failAttempts !== undefined && (!Number.isInteger(obj.failAttempts) || (obj.failAttempts as number) < 0 || (obj.failAttempts as number) > 5)) fields.push({ field: 'failAttempts', message: 'Must be an integer from 0 to 5.' });
  return fields;
};
const server = createServer(async (req, res) => {
  const pathname = new URL(req.url ?? '/', 'http://localhost').pathname;
  if (pathname === '/') {
    if (req.method !== 'GET') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' }); res.end(uiHtml); return;
  }
  if (pathname === '/health') {
    if (req.method !== 'GET') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    const row = db.prepare('SELECT at FROM worker_heartbeat WHERE id=1').get() as { at?: number } | undefined;
    return send(res, 200, { status: 'ok', worker: row && Date.now() - Number(row.at) < 3000 ? 'up' : 'down' });
  }
  if (pathname === '/api/jobs' && req.method === 'POST') {
    const issues: { field: string; message: string }[] = [];
    const keyHeader = req.headers['idempotency-key'];
    const key = typeof keyHeader === 'string' ? keyHeader : undefined;
    if (keyHeader !== undefined && (key === undefined || !/^[A-Za-z0-9_-]{1,128}$/.test(key))) issues.push({ field: 'Idempotency-Key', message: 'Must contain 1 to 128 letters, digits, underscores, or hyphens.' });
    const ct = req.headers['content-type'];
    if (!ct || !/^application\/json(?:\s*;|\s*$)/i.test(ct)) issues.push({ field: 'body', message: 'Content-Type must be application/json.' });
    let raw = '';
    try { raw = await readBody(req); } catch { issues.push({ field: 'body', message: 'Request body is too large.' }); }
    let parsed: unknown;
    if (!issues.some((x) => x.message === 'Request body is too large.')) {
      try { parsed = JSON.parse(raw); } catch { issues.push({ field: 'body', message: 'Body must be valid JSON.' }); }
    }
    if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
      if (parsed !== undefined) issues.push({ field: 'body', message: 'Body must be a JSON object.' });
    } else if (parsed) issues.push(...fieldsFor(parsed as Record<string, unknown>));
    if (issues.length) return error(res, 400, 'invalid_request', 'Request validation failed.', issues);
    const body = parsed as { input: string; steps?: number; failAttempts?: number };
    const payload = JSON.stringify({ input: body.input, steps: body.steps ?? 5, failAttempts: body.failAttempts ?? 0 });
    if (key) {
      const existing = db.prepare('SELECT i.payload, j.* FROM idempotency i JOIN jobs j ON j.id=i.job_id WHERE i.key=?').get(key) as (Record<string, unknown> & { payload: string }) | undefined;
      if (existing) {
        if (existing.payload !== payload) return error(res, 409, 'idempotency_conflict', 'Idempotency key was already used with a different payload.');
        return send(res, 200, mapJob(existing));
      }
    }
    const now = new Date().toISOString(); const id = randomUUID();
    db.exec('BEGIN IMMEDIATE');
    try {
      db.prepare('INSERT INTO jobs(id,status,input,steps,fail_attempts,attempts,progress_completed,result_output,error,created_at,updated_at,available_at) VALUES(?,?,?,?,?,0,0,NULL,NULL,?,?,0)')
        .run(id, 'queued', body.input, body.steps ?? 5, body.failAttempts ?? 0, now, now);
      if (key) db.prepare('INSERT INTO idempotency(key,payload,job_id) VALUES(?,?,?)').run(key, payload, id);
      db.exec('COMMIT');
    } catch (e) { db.exec('ROLLBACK'); throw e; }
    const row = db.prepare('SELECT * FROM jobs WHERE id=?').get(id) as Record<string, unknown>;
    return send(res, 201, mapJob(row));
  }
  if (pathname === '/api/jobs' && req.method === 'GET') {
    const rows = db.prepare('SELECT * FROM jobs ORDER BY created_at DESC, rowid DESC').all() as Record<string, unknown>[];
    return send(res, 200, { jobs: rows.map(mapJob) });
  }
  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (req.method !== 'GET') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    let id: string; try { id = decodeURIComponent(match[1]!); } catch { return error(res, 404, 'not_found', 'Job not found.'); }
    const row = db.prepare('SELECT * FROM jobs WHERE id=?').get(id) as Record<string, unknown> | undefined;
    return row ? send(res, 200, mapJob(row)) : error(res, 404, 'not_found', 'Job not found.');
  }
  if (pathname === '/api/jobs') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
  return error(res, 404, 'not_found', 'Route not found.');
});
const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => server.close(() => { db.close(); process.exit(0); }));

