import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, mapJob } from './db.ts';

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => { stopping = true; });
const heartbeat = db.prepare('INSERT INTO worker_heartbeat(id,at) VALUES(1,?) ON CONFLICT(id) DO UPDATE SET at=excluded.at');
function beat(): void { heartbeat.run(Date.now()); }

// A running row is owned only by the worker process that claimed it. On restart it
// is safe to queue again; progress is reset when the next attempt is claimed.
db.prepare("UPDATE jobs SET status='queued', available_at=0, updated_at=? WHERE status='running'").run(new Date().toISOString());
console.log('worker started');
try {
  while (!stopping) {
    beat();
    let job;
    db.exec('BEGIN IMMEDIATE');
    try {
      const row = db.prepare("SELECT * FROM jobs WHERE status='queued' AND available_at<=? ORDER BY created_at ASC, rowid ASC LIMIT 1").get(Date.now()) as Record<string, unknown> | undefined;
      if (row) {
        const now = new Date().toISOString();
        db.prepare("UPDATE jobs SET status='running', attempts=attempts+1, progress_completed=0, result_output=NULL, error=NULL, updated_at=? WHERE id=? AND status='queued'").run(now, String(row.id));
        job = db.prepare('SELECT * FROM jobs WHERE id=?').get(String(row.id)) as Record<string, unknown>;
      }
      db.exec('COMMIT');
    } catch (e) { db.exec('ROLLBACK'); throw e; }
    if (!job) { await sleep(100); continue; }
    const current = mapJob(job);
    if (current.attempts <= current.failAttempts) {
      if (current.attempts >= 3) {
        db.prepare("UPDATE jobs SET status='failed', error='transient failure', result_output=NULL, updated_at=? WHERE id=?").run(new Date().toISOString(), current.id);
      } else {
        db.prepare("UPDATE jobs SET status='queued', available_at=?, progress_completed=0, updated_at=? WHERE id=?").run(Date.now() + 500, new Date().toISOString(), current.id);
      }
      continue;
    }
    for (let n = 1; n <= current.steps && !stopping; n++) {
      await sleep(100);
      const now = new Date().toISOString();
      db.prepare("UPDATE jobs SET progress_completed=?, updated_at=? WHERE id=? AND status='running'").run(n, now, current.id);
      beat();
    }
    if (!stopping) {
      db.prepare("UPDATE jobs SET status='completed', progress_completed=steps, result_output=?, error=NULL, updated_at=? WHERE id=? AND status='running'")
        .run(current.input.toUpperCase(), new Date().toISOString(), current.id);
    }
  }
} finally {
  db.close();
  console.log('worker stopped');
}

