8	    body { font: 16px system-ui, sans-serif; max-width: 760px; margin: 2rem auto; padding: 0 1rem; color: #18212b; }
9	    form { display: grid; gap: .75rem; max-width: 520px; }
10	    label { display: grid; gap: .25rem; }
11	    input, button { font: inherit; padding: .5rem; }
12	    #form-error { color: #a01818; min-height: 1.25em; }
13	    #job-list { padding: 0; list-style: none; }
14	    [data-testid="job-item"] { border: 1px solid #ccd3da; border-radius: .4rem; padding: .8rem; margin: .6rem 0; }
15	    .meta { color: #53606d; }
16	  </style>
17	</head>
18	<body>
19	  <h1>Job tracker</h1>
20	  <form data-testid="job-form" id="job-form">
21	    <label>Input <input data-testid="job-input" name="input" type="text" required maxlength="1000"></label>
22	    <label>Steps <input data-testid="job-steps" name="steps" type="number" min="1" max="20" step="1" value="5"></label>
23	    <label>Fail attempts <input data-testid="job-fail-attempts" name="failAttempts" type="number" min="0" max="5" step="1" value="0"></label>
24	    <button data-testid="job-submit" type="submit">Submit job</button>
25	  </form>
26	  <div data-testid="form-error" id="form-error" role="alert" aria-live="polite"></div>
27	  <h2>Jobs</h2>
28	  <ul data-testid="job-list" id="job-list"></ul>
29	  <script>
30	    const form = document.querySelector('[data-testid="job-form"]');
31	    const errorRegion = document.querySelector('[data-testid="form-error"]');
32	    const list = document.querySelector('[data-testid="job-list"]');
33	    async function refresh() {
34	      try {
35	        const response = await fetch('/api/jobs');
36	        const data = await response.json();
37	        list.replaceChildren(...data.jobs.map(job => {
38	          const item = document.createElement('li');
39	          item.dataset.testid = 'job-item'; item.dataset.jobId = job.id;
40	          const title = document.createElement('strong'); title.textContent = job.input;
41	          const status = document.createElement('div'); status.dataset.testid = 'job-status'; status.textContent = job.status;
42	          const progress = document.createElement('div'); progress.dataset.testid = 'job-progress'; progress.textContent = `${job.progress.completed}/${job.progress.total}`;
43	          const result = document.createElement('div'); result.dataset.testid = 'job-result'; result.textContent = job.result ? job.result.output : (job.error || '');
44	          const meta = document.createElement('div'); meta.className = 'meta'; meta.textContent = `Attempts: ${job.attempts}`;
45	          item.append(title, status, progress, result, meta);
46	          return item;
47	        }));
48	      } catch { /* The next poll will refresh when the server is available. */ }
49	    }
50	    form.addEventListener('submit', async event => {
51	      event.preventDefault(); errorRegion.textContent = '';
52	      const data = new FormData(form);
53	      const payload = { input: data.get('input'), steps: Number(data.get('steps')), failAttempts: Number(data.get('failAttempts')) };
54	      try {
55	        const response = await fetch('/api/jobs', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(payload) });
56	        const result = await response.json();
57	        if (!response.ok) {
58	          const fields = result.error?.fields || [];
59	          errorRegion.textContent = fields.length ? fields.map(f => `${f.field}: ${f.message}`).join(' ') : (result.error?.message || 'Submission failed.');
60	        } else { form.elements.input.value = ''; await refresh(); }
61	      } catch { errorRegion.textContent = 'Could not submit the job. Please try again.'; }
62	    });
63	    refresh(); setInterval(refresh, 800);
64	  </script>
65	</body>
66	</html>
